import sys
import flax.linen as nn
import jax.numpy as jnp
import optax

sys.path.append('storage/episteme')
from fourier_forecaster_v2_ln import FourierForecasterLN

# Lazy-load the variance vector so it's only loaded once.
NEURON_VARIANCES = None

def _define_hyperparameters():
    return { 'learning_rate': 0.001, 'rank_k': 320, 'proj_rank': 36, 'curvature_strength': 1e-4 }

class ModelWrapper:
    def __init__(self, hparams):
        self.model = FourierForecasterLN(rank_k=hparams['rank_k'], proj_rank=hparams['proj_rank'])
        self.needs_rng = True
    def init(self, rng_key, dummy_input):
        return self.model.init({'params': rng_key, 'dropout': rng_key}, dummy_input)
    def apply(self, params, x, training=False, rngs=None):
        return self.model.apply(params, x, training=training, rngs=rngs)

def create_network(hparams):
    return ModelWrapper(hparams)

def compute_loss(predictions, targets, params, x):
    global NEURON_VARIANCES
    hparams = _define_hyperparameters()

    # Load the pre-computed variance vector on the first call
    if NEURON_VARIANCES is None:
        try:
            NEURON_VARIANCES = jnp.load('storage/logos/neuron_variances.npy')
        except FileNotFoundError:
            # Fallback to uniform weights if the file isn't found, to prevent crashing.
            NEURON_VARIANCES = jnp.ones(predictions.shape[-1])

    mae = jnp.mean(jnp.abs(predictions - targets))

    # Spatially-Adaptive Curvature Penalty
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]

    # Weighting: Inverse variance (more variance = less penalty)
    # Add epsilon for numerical stability
    epsilon = 1e-8
    weights = 1.0 / (NEURON_VARIANCES + epsilon)

    # Normalize weights to have a mean of 1, so the overall penalty strength is preserved
    weights = weights / jnp.mean(weights)

    # Apply weights to the squared curvature on a per-neuron basis
    weighted_curv_pen = jnp.mean(weights[None, None, :] * (curv * curv))

    return mae + hparams['curvature_strength'] * weighted_curv_pen

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate)
    )
